// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Differential run develop vs branch (WP9 3.11.6, Layer 3, case s20260929c388): after queries A, B and T have run twice
 * on a warm store, a committed {@code INSERT DATA { :b :p :c }} followed by B leaves T answering from the pre-write
 * state (no rows instead of {@code o=:b}). A fresh or reopened store, develop's LmdbStore and the MemoryStore return
 * the inserted row. The outcome also depends on JVM-wide state: run after other LMDB tests in the same fork the
 * sequence can come out right, so it runs in a fresh child JVM.
 */
public class LmdbStaleAnswerAfterInsertTest {

	private static final String PREFIX = "PREFIX : <http://ex/>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";

	@TempDir
	File dataDir;

	@Test
	public void insertIsVisibleAfterCrossQueryWarmup() throws Exception {
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Process process = new ProcessBuilder(List.of(java, "-Xmx1g", "--enable-native-access=ALL-UNNAMED", "-cp",
				System.getProperty("java.class.path"), Child.class.getName(), dataDir.getAbsolutePath()))
						.redirectErrorStream(true)
						.start();
		boolean finished = process.waitFor(120, TimeUnit.SECONDS);
		if (!finished) {
			process.destroyForcibly().waitFor(10, TimeUnit.SECONDS);
		}
		String output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
		assertTrue(finished, "child JVM did not finish\n" + output);
		assertEquals(0, process.exitValue(), "child JVM failed\n" + output);
		assertEquals("before=0 after=1",
				output.lines().filter(line -> line.startsWith("before=")).reduce((a, b) -> b).orElse(output));
	}

	/** Child JVM entry point: runs the warm-up, the write and the re-query; prints the row counts of T. */
	public static final class Child {

		private static int count(SailRepositoryConnection conn, String query) {
			int rows = 0;
			try (TupleQueryResult result = conn.prepareTupleQuery(PREFIX + query).evaluate()) {
				while (result.hasNext()) {
					result.next();
					rows++;
				}
			}
			return rows;
		}

		public static void main(String[] args) throws Exception {
			String a = "SELECT * WHERE { ?x :p ?y . FILTER(?y < 2) }";
			String b = "SELECT * WHERE { FILTER EXISTS { LATERAL { MINUS { ?y :r ?y . ?s :p ?y . } } } }";
			String t = "SELECT ?o WHERE { ?o :p :c }";
			SailRepository repository = new SailRepository(
					new LmdbStore(new File(args[0], "store"), new LmdbStoreConfig("spoc,posc")));
			repository.init();
			try (SailRepositoryConnection conn = repository.getConnection()) {
				conn.add(new StringReader(
						"@prefix : <http://ex/> .\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n"
								+ ":c :p \"1\"^^xsd:int .\n:c :r :a .\n"),
						"http://ex/", RDFFormat.TURTLE);
				int before = 0;
				for (int i = 0; i < 2; i++) {
					count(conn, a);
					count(conn, b);
					before = count(conn, t);
				}
				conn.prepareUpdate(PREFIX + "INSERT DATA { :b :p :c . }").execute();
				count(conn, b);
				System.out.println("before=" + before + " after=" + count(conn, t));
			} finally {
				repository.shutDown();
			}
		}
	}
}
